import{_ as a,o as s,c as i,a0 as o}from"./chunks/framework.DCluYYrN.js";const m=JSON.parse('{"title":"Módulo WebUI","description":"","frontmatter":{},"headers":[],"relativePath":"pt_BR/guide/module-webui.md","filePath":"pt_BR/guide/module-webui.md"}'),r={name:"pt_BR/guide/module-webui.md"};function t(n,e,p,d,l,c){return s(),i("div",null,[...e[0]||(e[0]=[o(`<h1 id="modulo-webui" tabindex="-1">Módulo WebUI <a class="header-anchor" href="#modulo-webui" aria-label="Permalink to &quot;Módulo WebUI&quot;">​</a></h1><p>Além de executar scripts de inicialização e modificar arquivos do sistema, os módulos do KernelSU também suportam a exibição de interfaces da UI e à interação direta com os usuários.</p><p>O módulo pode escrever páginas HTML + CSS + JavaScript através de qualquer tecnologia web. O gerenciador do KernelSU exibirá essas páginas através do WebView. Ele também fornece algumas APIs para interagir com o sistema, como executar comandos shell.</p><h2 id="diretorio-webroot" tabindex="-1">Diretório <code>webroot</code> <a class="header-anchor" href="#diretorio-webroot" aria-label="Permalink to &quot;Diretório \`webroot\`&quot;">​</a></h2><p>Os arquivos de recursos da web devem ser colocados no subdiretório <code>webroot</code> do diretório raiz do módulo, e <strong>DEVE</strong> haver um arquivo chamado <code>index.html</code>, que é a entrada da página do módulo. A estrutura do módulo mais simples contendo uma interface web é a seguinte:</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>❯ tree .</span></span>
<span class="line"><span>.</span></span>
<span class="line"><span>|-- module.prop</span></span>
<span class="line"><span>\`-- webroot</span></span>
<span class="line"><span>    \`-- index.html</span></span></code></pre></div><div class="warning custom-block"><p class="custom-block-title">AVISO</p><p>Ao instalar o módulo, KernelSU definirá automaticamente as permissões e o contexto do SELinux deste diretório. Se você não sabe o que está fazendo, não defina você mesmo as permissões deste diretório!</p></div><p>Se sua página contém CSS e JavaScript, você também precisa colocá-la neste diretório.</p><h2 id="api-javascript" tabindex="-1">API JavaScript <a class="header-anchor" href="#api-javascript" aria-label="Permalink to &quot;API JavaScript&quot;">​</a></h2><p>Se for apenas uma página de exibição, ela funcionará como uma página web comum. No entanto, o mais importante é que o KernelSU oferece uma série de APIs de sistema, permitindo a implementação de funções exclusivas do módulo.</p><p>O KernelSU disponibiliza uma biblioteca JavaScript, que está publicada no <a href="https://www.npmjs.com/package/kernelsu" target="_blank" rel="noreferrer">npm</a> e pode ser usada no código JavaScript das suas páginas web.</p><p>Por exemplo, você pode executar um comando shell para obter uma configuração específica ou modificar uma propriedade:</p><div class="language-JavaScript vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">JavaScript</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">import</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> { exec } </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">from</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;kernelsu&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">const</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> { </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">errno</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">stdout</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> } </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> exec</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;getprop ro.product.model&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span></code></pre></div><p>Para outro exemplo, você pode fazer com que a página web seja exibida em tela inteira ou exibir um dica.</p><p><a href="https://www.npmjs.com/package/kernelsu" target="_blank" rel="noreferrer">Documentação da API</a></p><p>Se você achar que a API existente não atende às suas necessidades ou é inconveniente de usar, fique à vontade para nos dar sugestões <a href="https://github.com/tiann/KernelSU/issues" target="_blank" rel="noreferrer">aqui</a>!</p><h2 id="algumas-dicas" tabindex="-1">Algumas dicas <a class="header-anchor" href="#algumas-dicas" aria-label="Permalink to &quot;Algumas dicas&quot;">​</a></h2><ol><li>Você pode usar <code>localStorage</code> normalmente para armazenar alguns dados, mas tenha em mente que eles serão perdidos caso o app gerenciador seja desinstalado. Se precisar de armazenamento persistente, será necessário gravar os dados manualmente em algum diretório.</li><li>Para páginas simples, recomendamos o uso do <a href="https://parceljs.org/" target="_blank" rel="noreferrer">parceljs</a> para empacotamento. Ele não exige configuração inicial e é extremamente prático de usar. No entanto, se você é um especialista em front-end ou possui suas próprias preferências, sinta-se à vontade para usar a ferramenta de sua escolha!</li></ol>`,18)])])}const h=a(r,[["render",t]]);export{m as __pageData,h as default};
